export function useJobAgentRequirements(
  jobId: string,
  cloudImagesQueryRef: PreloadedQuery<JobAgentRequirementsCloudImagesQuery>,
) {
  const dispatch = useAppDispatch()
  const id = usePipelineId()
  const jobAgent = useAppSelector(getRunsOn(jobId, id))
  const cloudImage =
    usePreloadedQuery(cloudImagesQuery, cloudImagesQueryRef)?.cloudImages?.cloudImage ?? emptyArray
  const agents: SelectItem[] = useMemo(
    () =>
      [...cloudImage, ...getCustomAgents()]
        .reduce<SelectItem[]>((acc, {name}) => {
          if (name) {
            const label = name.replaceAll('-', ' ')
            const osName = getCloudImageOsName(label)
            const glyph = cloudImageHardwareIcon[osName]
            const details = getCloudImageDetials(osName, label)

            acc.push({
              label,
              glyph,
              details,
              key: name,
              className: styles.selectItem,
            })
          }

          return acc
        }, [])

        .sort(sortCloudImages),
    [cloudImage],
  )
  const selectedCloudImage = useMemo(
    () => agents.find(({key}) => key === jobAgent),
    [agents, jobAgent],
  )
  const handlerCloudImageSelect = (value: SelectItem | null) =>
    dispatch(
      pipelineDraft.actions.setAgent({
        id,
        jobId,
        agent: value?.key?.toString(),
      }),
    )
  const isFiltered = agents.length > minCloudImages
  const isNoAgents = !agents.length
  const isSelected = !!selectedCloudImage
  const label = isNoAgents ? 'No agents available' : 'Please select any agent'

  return {
    label,
    isSelected,
    isNoAgents,
    selectedCloudImage,
    agents,
    isFiltered,
    handlerCloudImageSelect,
  }
}

function useStoredJobAgentRequirements() {
  const {setValueToStoredSettings, getValueFromStoredSettings} = useStoredSettingsValue()

  const storedSelfHostedRequirementKey = 'JOB_AGENT_SELF_HOSTED_REQUIREMENTS'
  const storedJetBrainsHostedRequirementKey = 'JOB_AGENT_JETBRAINS_HOSTED_REQUIREMENTS'

  const storedSelfHostedValue = getValueFromStoredSettings(storedSelfHostedRequirementKey) as
    | RunsOn
    | undefined

  const storedJetBrainsHostedValue = getValueFromStoredSettings(
    storedJetBrainsHostedRequirementKey,
  ) as RunsOn | undefined

  const setSelfHostedRequirement = useCallback(
    (value: RunsOn | undefined) => {
      setValueToStoredSettings(storedSelfHostedRequirementKey, value as SettingsStoreValue)
    },
    [storedSelfHostedRequirementKey, setValueToStoredSettings],
  )

  const setJetBrainsRequirement = useCallback(
    (value: RunsOn | undefined) => {
      setValueToStoredSettings(storedJetBrainsHostedRequirementKey, value as SettingsStoreValue)
    },
    [storedJetBrainsHostedRequirementKey, setValueToStoredSettings],
  )

  return {
    storedSelfHostedValue,
    storedJetBrainsHostedValue,
    setSelfHostedRequirement,
    setJetBrainsRequirement,
  }
}

export function useJobAgentRequirement(jobId: string) {
  const id = usePipelineId()

  const originalRunsOn = useAppSelector(state => getOriginalRunsOn(jobId, id)(state))
  const runsOn = useAppSelector(state => getRunsOn(jobId, id)(state))
  const isSelfHostedMode = isSelfHostedRunsOn(runsOn)

  const {
    storedSelfHostedValue,
    storedJetBrainsHostedValue,
    setSelfHostedRequirement,
    setJetBrainsRequirement,
  } = useStoredJobAgentRequirements()

  const dispatch = useAppDispatch()
  const handleSelfHostedClick = useEventCallback(() => {
    if (isSelfHostedMode) {
      return
    }
    function getNextRequirement() {
      if (storedSelfHostedValue != null) {
        return storedSelfHostedValue
      }
      return isSelfHostedRunsOn(originalRunsOn) ? originalRunsOn : undefined
    }

    setJetBrainsRequirement(runsOn)
    dispatch(
      pipelineDraft.actions.setSelfHostedAgent({
        id,
        jobId,
        requirements: getNextRequirement(),
      }),
    )
  })
  const handleJetBrainsHosted = useEventCallback(() => {
    if (!isSelfHostedMode) {
      return
    }

    function getNextAgent() {
      if (storedJetBrainsHostedValue != null) {
        return storedJetBrainsHostedValue
      }
      return isSelfHostedRunsOn(originalRunsOn) ? undefined : originalRunsOn
    }

    const nextAgent = getNextAgent()

    setSelfHostedRequirement(runsOn)
    dispatch(
      pipelineDraft.actions.setAgent({
        id,
        jobId,
        agent: typeof nextAgent === 'string' ? nextAgent : undefined,
      }),
    )
  })

  return {
    isSelfHostedMode,
    handleJetBrainsHosted,
    handleSelfHostedClick,
  }
}

export function useAgentCompatibilities(jobId: string, requirements: Array<SelfHostedRequirement>) {
  const {
    getCompatibilitieAgentsByJobId,
    getIsCurrentAgentIncompatibleByJobId,
    fetchAgentCompatibilities,
    isAgentCompatibilitiesLoading: isLoading,
  } = useMapAgentCompatibilities()
  const compatibilitieAgents = useMemo(() => {
    const agents = getCompatibilitieAgentsByJobId(jobId) ?? []
    if (isPipelinesEnabledInExclusiveMode()) {
      return agents?.filter(({agent}) => agent.type === 'AGENT')
    }
    return agents
  }, [jobId, getCompatibilitieAgentsByJobId])
  const isCurrentAgentIncompatibleByJobId = getIsCurrentAgentIncompatibleByJobId(jobId)
  const selfHostedAgents = useMemo(() => {
    if (isPipelinesEnabledInExclusiveMode()) {
      return compatibilitieAgents.filter(compatibility => {
        const jbHostedRequirement = compatibility.unmetReqirements.find(
          requirement =>
            requirement.parameter === 'teamcity.agent.jbHosted' &&
            requirement.predicate === 'does not equal' &&
            requirement.value === 'true',
        )

        return jbHostedRequirement == null
      })
    }
    return compatibilitieAgents
  }, [compatibilitieAgents])
  const selfHostedCompatibleAgents = useMemo(
    () => selfHostedAgents.filter(compatibility => compatibility.compatible),
    [selfHostedAgents],
  )

  useEffect(() => {
    if (isPipelineCompatibilityAgentsEnabled) {
      fetchAgentCompatibilities(true)
    }
  }, [fetchAgentCompatibilities, requirements])

  return {
    selfHostedAgents,
    selfHostedCompatibleAgents,
    isLoading,
    isCurrentAgentIncompatibleByJobId,
  }
}

export function useAuthorizablePoolId() {
  const {data} = restApi.endpoints.getPoolPermissions.useQuery()

  return useMemo(() => {
    if (!data) {
      return null
    }

    return data[selfHostedAuthPoolId]?.canAuthorized
      ? selfHostedAuthPoolId
      : (Object.values(data).find(pool => pool.canAuthorized)?.poolId ?? null)
  }, [data])
}
