import type {SelectItem} from '@jetbrains/ring-ui-built/components/select/select'

import {
  cloudImageHardwareCpu,
  cloudImageHardwareDetails,
  cloudImageHardwareOsOrder,
  cloudImageHardwareSize,
  cloudImageHardwareOs,
  cloudImageHardwareSizeOrder,
} from './JobAgentRequirements.consts'
import type {CloudImageHardwareOs, CloudImageHardwareSize} from './JobAgentRequirements.types'

export function getCloudImageOsName(name: string) {
  const cloudImageHardwareOsKeys = Object.values<CloudImageHardwareOs>(cloudImageHardwareOs)
  const nameLowerCase = name.toLowerCase()

  for (const key of cloudImageHardwareOsKeys) {
    const isExist = nameLowerCase.includes(key)

    if (isExist) {
      return cloudImageHardwareOs[key]
    }
  }

  return cloudImageHardwareOs.unknow
}

function getCloudImageSize(name: string) {
  const cloudImageHardwareSizeKeys = Object.values<CloudImageHardwareSize>(cloudImageHardwareSize)
  const nameLowerCase = name.toLowerCase()

  for (const key of cloudImageHardwareSizeKeys) {
    const isExist = nameLowerCase.includes(key)

    if (isExist) {
      return cloudImageHardwareSize[key]
    }
  }

  return cloudImageHardwareOs.unknow
}

export function getCloudImageDetials(osName: CloudImageHardwareOs, name: string) {
  const cloudImageHardwareDetailsOs = cloudImageHardwareDetails?.[osName]
  const sizesKeys = Object.values<CloudImageHardwareSize>(cloudImageHardwareSize)
  const isCpuArm = name.toLowerCase().includes(cloudImageHardwareCpu.arm)
  const nameLowerCase = name.toLowerCase()

  for (const key of sizesKeys) {
    const isExist = nameLowerCase.includes(key)
    const cpuDetails = cloudImageHardwareDetailsOs?.[key]

    if (isExist && cpuDetails) {
      const details = isCpuArm ? cpuDetails.arm : cpuDetails.x86_64

      return details?.join(` / `)
    }
  }

  return ''
}

export function sortCloudImages(current: SelectItem, prev: SelectItem) {
  const currentLabel = `${current.label}`
  const prevLabel = `${prev.label}`
  const imageOsName = getCloudImageOsName(currentLabel)
  const prevImageOsName = getCloudImageOsName(prevLabel)
  const imageSize = getCloudImageSize(currentLabel)
  const prevImageSize = getCloudImageSize(prevLabel)
  const orderOs = cloudImageHardwareOsOrder[imageOsName]
  const prevOrderOs = cloudImageHardwareOsOrder[prevImageOsName]
  const orderSize = cloudImageHardwareSizeOrder[imageSize]
  const prevOrderSize = cloudImageHardwareSizeOrder[prevImageSize]

  if (imageOsName === prevImageOsName) {
    return orderSize - prevOrderSize
  }

  return orderOs - prevOrderOs
}
