import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonGroup from '@jetbrains/ring-ui-built/components/button-group/button-group'
import Dialog, {type DialogAttrs} from '@jetbrains/ring-ui-built/components/dialog/dialog'
import {Header, Content} from '@jetbrains/ring-ui-built/components/island/island'
import {memo} from 'react'

import useBooleanState from '../../../../../../hooks/useBooleanState'

import InstallAgentDocker from './Docker/InstallAgentDocker'
import InstallAgentManually from './Manually/InstallAgentManually'

import styles from './InstallAgentDialog.module.css'

interface Props {
  isManuallyDefault?: boolean
  poolId?: number
}

function InstallAgentDialog(props: Props & DialogAttrs) {
  const {isManuallyDefault = true, poolId, ...restProps} = props
  const {onCloseAttempt} = props
  const [isManually, setManually, setDockerImage] = useBooleanState(isManuallyDefault)

  return (
    <Dialog
      data-test={'self-hosted-agent-install'}
      trapFocus
      autoFocusFirst
      show
      showCloseButton
      closeButtonInside
      contentClassName={styles.dialog}
      {...restProps}
    >
      <Header>{'Install Self-hosted agent'}</Header>
      <Content className={styles.content}>
        <ButtonGroup>
          <Button data-test={'manually'} active={isManually} onClick={setManually}>
            {'Manually'}
          </Button>
          <Button data-test={'docker-image'} active={!isManually} onClick={setDockerImage}>
            {'Docker Image'}
          </Button>
        </ButtonGroup>
        {isManually ? (
          <InstallAgentManually poolId={poolId} />
        ) : (
          <InstallAgentDocker poolId={poolId} />
        )}
        <Button data-test={'got-it'} className={styles.button} primary onClick={onCloseAttempt}>
          {'Got it'}
        </Button>
      </Content>
    </Dialog>
  )
}

export default memo(InstallAgentDialog)
