import AddIcon from '@jetbrains/icons/add.svg'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import type {ReactNode} from 'react'
import {useId, memo} from 'react'

import useBooleanState from '../../../../../../hooks/useBooleanState'
import {useAuthorizablePoolId} from '../../JobAgentRequirements.hooks'
import InstallAgentDialog from '../InstallDialog/InstallAgentDialog'

import styles from './InstallAgent.module.css'

interface Props {
  children?: ReactNode
  className?: string
  buttonClassName?: string
  inline?: boolean
  primary?: boolean
}

const popupProps = {
  top: 0,
  offset: 8,
}

function InstallAgent(props: Props) {
  const {inline, primary, className, buttonClassName, children} = props
  const id = useId()
  const [isOpenDialog, openDialog, closeDialog] = useBooleanState(false)
  const authorizablePoolId = useAuthorizablePoolId()
  const canInstallAgent = authorizablePoolId != null

  return (
    <>
      <Tooltip
        delay={700}
        className={className}
        title={
          canInstallAgent
            ? 'Install self-hosted agent'
            : 'You do not have permissions to set up build agents. Contact an administrator to request access.'
        }
        popupProps={popupProps}
        id={id}
      >
        <Button
          disabled={!canInstallAgent}
          aria-labelledby={id}
          data-test={'install-agent'}
          className={classNames(styles.button, buttonClassName)}
          inline={inline}
          primary={primary}
          onClick={openDialog}
          icon={!children && AddIcon}
        >
          {children && (
            <div className={styles.container}>
              <SvgIcon className={styles.icon} icon="add" />
              <span className={styles.children}>{children}</span>
            </div>
          )}
        </Button>
      </Tooltip>

      {isOpenDialog && canInstallAgent && (
        <InstallAgentDialog poolId={authorizablePoolId} onCloseAttempt={closeDialog} />
      )}
    </>
  )
}

export default memo(InstallAgent)
