import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonGroup from '@jetbrains/ring-ui-built/components/button-group/button-group'
import {memo, useState} from 'react'

import {Size} from '../../../../../../../components/Input'
import Input from '../../../../../../../components/Input/Input'
import useBooleanState from '../../../../../../../hooks/useBooleanState'
import styles from '../InstallAgentDialog.module.css'
import InstallAgentScript from '../Script/InstallAgentScript'

import {useCode} from './InstallAgentManually.hooks'

type Props = {
  poolId?: number
}

function InstallAgentManually({poolId}: Props) {
  const [isUnix, setUnix, setWindows] = useBooleanState(true)
  const [agentName, setAgentName] = useState('My agent')
  const {unix, windows} = useCode({
    agentName,
    poolId,
  })
  const script = isUnix ? unix : windows

  return (
    <div className={styles.innerContent}>
      <ButtonGroup>
        <Button data-test={'linux'} active={isUnix} onClick={setUnix}>
          {'Linux/Mac'}
        </Button>
        <Button data-test={'windows'} active={!isUnix} onClick={setWindows}>
          {'Windows'}
        </Button>
      </ButtonGroup>
      <Input
        data-test={'agent-name'}
        className={styles.input}
        label={'Agent name'}
        type="text"
        spellCheck={false}
        size={Size.FULL}
        value={agentName}
        onChange={e => setAgentName(e.currentTarget.value)}
        autoFocus
      />
      <div className={styles.text}>
        {
          'Run the following script on your agent machine to install and start an agent from the ZIP archive:'
        }
      </div>
      <InstallAgentScript display={script.display} code={script.code} />
    </div>
  )
}

export default memo(InstallAgentManually)
