import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonGroup from '@jetbrains/ring-ui-built/components/button-group/button-group'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import {memo, useState} from 'react'

import {Size} from '../../../../../../../components/Input'
import Input from '../../../../../../../components/Input/Input'
import useBooleanState from '../../../../../../../hooks/useBooleanState'
import styles from '../InstallAgentDialog.module.css'
import InstallAgentScript from '../Script/InstallAgentScript'

import {useCode} from './InstallAgentDocker.hooks'

type Props = {
  poolId?: number
}

function InstallAgentDocker({poolId}: Props) {
  const [isUnix, setUnix, setWindows] = useBooleanState(true)
  const [agentName, setAgentName] = useState('My agent')
  const {unix, windows, outOfDocker} = useCode({
    agentName,
    poolId,
  })

  return (
    <div className={styles.innerContent}>
      <ButtonGroup>
        <Button active={isUnix} onClick={setUnix}>
          {'Linux/Mac'}
        </Button>
        <Button active={!isUnix} onClick={setWindows}>
          {'Windows'}
        </Button>
      </ButtonGroup>
      <Input
        data-test={'agent-name'}
        className={styles.input}
        label={'Agent name'}
        type="text"
        spellCheck={false}
        size={Size.FULL}
        value={agentName}
        onChange={e => setAgentName(e.currentTarget.value)}
        autoFocus
      />
      <div className={styles.text}>
        {
          'Run the following command on your agent machine to start an Alpine Linux-based agent from the '
        }
        <Link
          target="_blank"
          href={'https://hub.docker.com/r/jetbrains/teamcity-agent/'}
          rel="noreferrer"
        >
          {'official image.'}
        </Link>
      </div>
      {isUnix ? (
        <>
          <InstallAgentScript display={unix.display} code={unix.code} />
          <InstallAgentScript display={outOfDocker.display} code={outOfDocker.code} />
        </>
      ) : (
        <InstallAgentScript display={windows.display} code={windows.code} />
      )}
    </div>
  )
}

export default memo(InstallAgentDocker)
