import Code from '@jetbrains/ring-ui-built/components/code/code'
import {memo} from 'react'

import CopyIconButton from '../../../../../../../../../common/CopyIconButton/CopyIconButton'
import styles from '../InstallAgentDialog.module.css'

interface Props {
  code: string
  display?: string
}

function InstallAgentScript(props: Props) {
  const {code, display = code} = props
  return (
    <div className={styles.scriptContainer}>
      <CopyIconButton
        iconClassName={styles.copyIcon}
        wrapperClassName={styles.copy}
        text={code}
        withBorder
      />
      <Code language="bash" code={display} className={styles.script} softWrap />
    </div>
  )
}

export default memo(InstallAgentScript)
