import {baseUri} from '@jetbrains/teamcity-ui'
import {useMemo} from 'react'

import {restApi} from '../../../../../../../../../../services/rest'
import {selfHostedAuthPoolId} from '../../../JobAgentRequirements.consts'
import {getCopyCode} from '../InstallAgentDialog.utils'

interface Props {
  agentName: string
  poolId?: number
}

export function useCode(props: Props) {
  const {agentName, poolId} = props

  const {agentToken} = restApi.endpoints.agentAuthorizationToken.useQuery(
    {
      agentPoolId: poolId ?? selfHostedAuthPoolId,
      count: 1,
      timeToLiveSeconds: 86400,
    },
    {
      selectFromResult: state => ({
        agentToken: state.data?.item[0],
      }),
      refetchOnMountOrArgChange: 30,
    },
  )

  return useMemo(() => {
    const unix = `
# Docker-based Agent without Docker-in-Docker
docker run -e SERVER_URL="${baseUri}" \
-e AGENT_NAME="${agentName}" \
-e AGENT_TOKEN="${agentToken}" \
jetbrains/teamcity-agent
`
    const outOfDocker = `
# Docker-out-of-Docker (connect to Docker on host)
docker run  -e SERVER_URL="${baseUri}"  \
-e AGENT_NAME="${agentName}" \
-e AGENT_TOKEN="${agentToken}" \
-u 0 \
-v $(pwd)/buildagent/config:/data/teamcity_agent/conf \
-v /var/run/docker.sock:/var/run/docker.sock  \
-v /opt/buildagent/work:/opt/buildagent/work \
-v /opt/buildagent/temp:/opt/buildagent/temp \
-v /opt/buildagent/tools:/opt/buildagent/tools \
-v /opt/buildagent/plugins:/opt/buildagent/plugins \
-v /opt/buildagent/system:/opt/buildagent/system \
jetbrains/teamcity-agent
`
    const windows = `
docker run -e SERVER_URL="${baseUri}" \
-e AGENT_NAME="${agentName}" \
-e AGENT_TOKEN="${agentToken}" \
jetbrains/teamcity-agent
`

    return {
      unix: {
        display: unix,
        code: getCopyCode(unix),
      },
      windows: {
        display: windows,
        code: getCopyCode(windows),
      },
      outOfDocker: {
        display: outOfDocker,
        code: getCopyCode(outOfDocker),
      },
    }
  }, [agentName, agentToken])
}
