import {baseUri} from '@jetbrains/teamcity-ui'
import {resolveRelative} from '@jetbrains/teamcity-ui/dist/utils'
import {useMemo} from 'react'

import {restApi} from '../../../../../../../../../../services/rest'
import {selfHostedAuthPoolId} from '../../../JobAgentRequirements.consts'
import {getCopyCode} from '../InstallAgentDialog.utils'

interface Props {
  agentName: string
  poolId?: number
}

const url = resolveRelative('/update/buildAgentFull.zip')

export function useCode(props: Props) {
  const {agentName, poolId} = props

  const {agentToken} = restApi.endpoints.agentAuthorizationToken.useQuery(
    {
      agentPoolId: poolId ?? selfHostedAuthPoolId,
      count: 1,
      timeToLiveSeconds: 86400,
    },
    {
      selectFromResult: state => ({
        agentToken: state.data?.item[0],
      }),
      refetchOnMountOrArgChange: 30,
    },
  )

  return useMemo(() => {
    const unix = `
# Download the buildAgentFull.zip file
curl -o buildAgentFull.zip ${url}

# Extract the downloaded archive
unzip buildAgentFull.zip -d buildAgent

# Rename the buildAgent.dist.properties file to buildAgent.properties
mv buildAgent/conf/buildAgent.dist.properties buildAgent/conf/buildAgent.properties

# Set the 'name' property
sed -i '' 's|^name=.*|name=${agentName}|' buildAgent/conf/buildAgent.properties

# Set the 'authorizationToken'
sed -i '' 's|^authorizationToken=.*|authorizationToken=${agentToken}|' buildAgent/conf/buildAgent.properties

# Set the 'serverUrl' property
sed -i '' 's|^serverUrl=.*|serverUrl=${baseUri}|' buildAgent/conf/buildAgent.properties

# Give execution permissions to the agent.sh script
chmod +x buildAgent/bin/agent.sh

# Execute the agent.sh script
buildAgent/bin/agent.sh start
`
    const windows = `
# Download the buildAgentFull.zip file
Invoke-WebRequest -Uri ${url} -OutFile buildAgentFull.zip

# Extract the downloaded archive
Expand-Archive -Path buildAgentFull.zip -DestinationPath buildAgent

# Rename the buildAgent.dist.properties file to buildAgent.properties
Rename-Item -Path buildAgent/conf/buildAgent.dist.properties -NewName buildAgent.properties

# Set the 'name' property
(Get-Content buildAgent/conf/buildAgent.properties) -replace '^name=.*', 'name=${agentName}' | Set-Content buildAgent/conf/buildAgent.properties

# Set the 'authorizationToken' property
(Get-Content buildAgent/conf/buildAgent.properties) -replace '^authorizationToken=.*', 'authorizationToken=${agentToken}' | Set-Content buildAgent/conf/buildAgent.properties

# Set the 'serverUrl' property
(Get-Content buildAgent/conf/buildAgent.properties) -replace '^serverUrl=.*', 'serverUrl=${baseUri}' | Set-Content buildAgent/conf/buildAgent.properties

# Give execution permissions to the agent.sh script
chmod +x buildAgent/bin/agent.sh

# Execute the agent.sh script
./buildAgent/bin/agent.sh start
`
    return {
      unix: {
        display: unix,
        code: getCopyCode(unix),
      },
      windows: {
        display: windows,
        code: getCopyCode(windows),
      },
    }
  }, [agentName, agentToken])
}
